		int iterations = TriggerCount;
		for (int i = 0; i < iterations; i++)
		{
			await CreatureCmd.Damage(new ThrowingPlayerChoiceContext(), base.Owner, base.Amount, ValueProp.Unblockable | ValueProp.Unpowered, null, null);
